files=changed('squlearn_274_279');D['squlearn_274_279']=dict(oracle_files=[x for x in files if '/kernel/' in x or x.endswith('approximated_gradients.py')],task=dict(problem_statement='Quantum-kernel optimization needs to work as part of the high-level regression and classification models. Users should be able to wrap an existing kernel with an optimizer and have model fitting optimize the kernel parameters.',requirements=['Provide a quantum-kernel optimizer usable wherever a quantum kernel is accepted by the supported models.','Fit optimized kernels through QGPR, QKRR, QSVR, QGPC, and QSVC.','Retain the selected optimizer, fitted state, and optimal parameter values after fitting.','Support negative log likelihood for fidelity kernels and target alignment for projected kernels.'],interface=[api('Class','KernelOptimizer','src/squlearn/kernel/matrix/kernel_optimizer.py','constructor: quantum_kernel, loss=None, optimizer=None, initial_parameters=None','','Wraps a quantum kernel and exposes fitted state and optimized parameters.'),api('Method','KernelOptimizer.get_optimal_parameters','src/squlearn/kernel/matrix/kernel_optimizer.py','self','numpy.ndarray','Returns the optimized kernel parameters after fitting.'),api('Class','NLL','src/squlearn/kernel/loss/negative_log_likelihood.py','constructor: sigma=1.0','','Kernel negative-log-likelihood loss.'),api('Class','TargetAlignment','src/squlearn/kernel/loss/target_alignment.py','constructor:','','Kernel target-alignment loss.')]+[api('Method',name+'.fit','src/squlearn/kernel/ml/'+name.lower()+'.py','self, X, y',name,'Fits the model and its wrapped kernel optimizer.') for name in ['QGPR','QKRR','QSVR','QGPC','QSVC']]))
